function build(name,x,y,dark){const r=screen(name,x,y,{dark});sidebarA(r,{av:"NS",avFill:"#18181B",title:"Northwind Studio",subtitle:"Install · Superadmin",sections:INSTALL_SECTIONS,active:"Workspaces",role:"Superadmin"});
const m=mainCol(r);topbarA(m,["Install","Workspaces"],{site:false});
const ban=fr(m,"Master key banner",{width:"fill_container",padding:[14,32],gap:14,alignItems:"center",fill:"$warn-bg",stroke:"$border",strokeWidth:{bottom:1}});ic(ban,"key-round",{width:20,height:20,fill:"$warn"});const bt=fr(ban,"Text",{layout:"vertical",gap:2,width:"fill_container"});tx(bt,"Back up your master key",{fontWeight:"600"});tx(bt,"WEBCRAFT_SECRET_KEY encrypts every SMTP password, AI key and API token on this Install. If it is lost, they cannot be recovered. Keep a copy somewhere other than this server.",{fill:"$fg",textGrowth:"fixed-width",width:"fill_container",lineHeight:1.45});btn(ban,"How to back up");btn(ban,"I've backed it up",{kind:"primary"});
const head=fr(m,"Page header",{width:"fill_container",padding:[24,32,16,32],alignItems:"end",gap:16});const l=fr(head,"Title block",{layout:"vertical",gap:4,width:"fill_container"});tx(l,"Workspaces",{fontSize:22,fontWeight:"600"});tx(l,"12 client organisations on this Install",{fill:"$muted-fg"});btn(head,"New Workspace",{kind:"primary",icon:"plus"});
const tw=fr(m,"Table wrap",{width:"fill_container",padding:[0,32,24,32]});const t=fr(tw,"Table",{layout:"vertical",width:"fill_container",cornerRadius:8,stroke:"$border",strokeWidth:1,clip:true});
const W=["fill_container",90,100,200,170,120];
const row=(cells,hdr)=>{const rr=fr(t,"Row",{width:"fill_container",height:hdr?38:50,padding:[0,16],gap:14,alignItems:"center",...(hdr?{fill:"$muted"}:{stroke:"$border",strokeWidth:{top:1}})});cells.forEach((c,i)=>{const cell=fr(rr,"Cell",{width:W[i],alignItems:"center",gap:8});c(cell);});};
const H=s=>c=>tx(c,s,{fontSize:12,fontWeight:"500",fill:"$muted-fg"});
row([H("Workspace"),H("Sites"),H("Members"),H("Staff assigned"),H("AI usage this month"),H("Created")],true);
for(const [a,n,f,s,mm,stf,ai,cr] of [["AC","Acme Ltd","#D97706",3,7,"Davide, Ciara","€4.10 of €10 cap","Jan 2026"],["NB","Nimbus Bikes","#059669",1,3,"Ciara","Own AI key","Mar 2026"],["VT","Verde Travel","#7C3AED",2,5,"Davide, Tom","€9.20 of €10 cap","Apr 2026"],["OS","Oakfield School","#DB2777",1,12,"Tom","AI off","Jun 2026"],["HB","Harbour Dental","#0891B2",1,2,"Ciara","€0.40 of €10 cap","Sep 2026"]]){row([c=>{avatar(c,a,{square:true,size:24,fill:f,fs:9});tx(c,n,{fontWeight:"500"});},c=>tx(c,s),c=>tx(c,mm),c=>tx(c,stf,{fill:"$muted-fg"}),c=>ai.includes("9.20")?badge(c,ai,"warn"):tx(c,ai,{fill:"$muted-fg"}),c=>tx(c,cr,{fill:"$muted-fg"})]);}
return r;}
const a=build("Superadmin · Workspaces + master key banner",1540,2000,false);const b=build("Superadmin · Dark",3080,2000,true);
Export([a,b],"png","/tmp/penproto/out");
